import{_ as o,o as l,c as e,am as r}from"./chunks/framework._FJXuPhs.js";const _=JSON.parse('{"title":"DDD 架构模式","description":"","frontmatter":{"title":"DDD 架构模式","excerpt":"摘要","date":"2025-09-30 14:06:29","updated":"2025-09-30 14:06:29"},"headers":[],"relativePath":"架构篇/系统架构设计/架构模式/DDD 分层架构/什么是 DDD领域驱动设计/DDD 架构模式.md","filePath":"架构篇/系统架构设计/架构模式/DDD 分层架构/什么是 DDD领域驱动设计/DDD 架构模式.md","lastUpdated":null}'),p={name:"架构篇/系统架构设计/架构模式/DDD 分层架构/什么是 DDD领域驱动设计/DDD 架构模式.md"};function i(D,t,a,s,n,c){return l(),e("div",null,[...t[0]||(t[0]=[r('<p>教程围绕了 上、中、下 三个篇幅，去讲述了 DDD 的一个整体概念。</p><h3 id="理论篇" tabindex="-1">理论篇 <a class="header-anchor" href="#理论篇" aria-label="Permalink to &quot;理论篇&quot;">​</a></h3><p>理论基础篇： <a href="https://wx.zsxq.com/group/48411118851818/topic/411244188545488" target="_blank" rel="noreferrer">https://wx.zsxq.com/group/48411118851818/topic/411244188545488</a></p><blockquote><p>DDD（Domain-Driven Design，领域驱动设计）</p></blockquote><p>DDD 是由 Eric Evans 在其著作《领域驱动设计：软件核心复杂性应对之道》中提出的软件设计方法。它<strong>不是</strong>一种具体的工程结构（如 MVC），也<strong>不等同于</strong>微服务架构，更<strong>不是</strong>单一的设计模式。</p><p>通过业务角度做区分，通过领域方式去代码结构进行处理。结合实际业务，以及工程设计角度，的一种指导思想（没有强制的某种范式）</p><p>DDD 核心聚焦：业务领域，解决核心复杂性；</p><p>如果业务不太复杂，其实也不用使用DDD，DDD主要的目的，还是类似解耦吧，通过业务领域纬度。</p><p>大的前提</p><ul><li>1、领域划分</li><li>2、统一语言</li><li>3、限界上下文</li></ul><p>实际使用的时候划分</p><ul><li>实体</li><li>值对象（实际就是 Model )</li><li>聚合 AppService</li><li>领域服务 Service</li><li>仓储（Repository)</li><li></li></ul><p>教程提到的一些概念：</p><blockquote><p>充血模型 和 贫血模型</p></blockquote><p>传统的 MVC 架构（Service + 数据模型）往往是“贫血模型”，导致 Service 层逻辑臃肿、难以维护；而 DDD 提倡“<strong>充血模型</strong>”，将属性和行为逻辑聚合在对象中，使代码结构更贴近真实业务逻辑</p><blockquote><p>聚合对象</p></blockquote><p>看教程，聚合对象更像是业务领域下的某个单独事务方法控制的动作场景。</p><blockquote><p>适配器</p></blockquote><p>端口，是对外提供的窗口</p><p>适配器，具体的实现。</p><p>在 DDD 架构中，调用外部接口遵循以下逻辑：</p><ol><li><strong>定义标准（依赖倒置）</strong>：领域层不直接依赖外部的 RPC 或 HTTP 接口，而是定义一个含有出入参对象的<strong>接口标准（Port）</strong>。这被称为<strong>依赖倒置</strong>，即核心逻辑依赖于抽象接口，而不是具体实现。</li><li><strong>实现调用（适配器封装）</strong>：在基础设施层创建一个适配器类，注入外部服务的客户端（如 HttpClient 或 RPC 客户端），实现领域层定义的接口。</li><li><strong>防止污染（防腐层）</strong>：领域层只关心自身的业务模型，通过端口和适配器，外部系统的数据模型被转换成领域对象。这样即使外部接口发生变化，也只需要修改适配器代码，而不会污染核心领域逻辑</li></ol><h3 id="场景使用" tabindex="-1">场景使用 <a class="header-anchor" href="#场景使用" aria-label="Permalink to &quot;场景使用&quot;">​</a></h3><p>场景使用： <a href="https://wx.zsxq.com/group/48411118851818/topic/411241255841118" target="_blank" rel="noreferrer">https://wx.zsxq.com/group/48411118851818/topic/411241255841118</a></p><p>场景主要有：</p><ul><li>支付宝扫码支付操作</li><li>TLDraw 设计图生成前端代码操作 <ul><li>使用大模型，TLDraw 保存图片后给大模型识别，然后生成对应前端代码</li></ul></li><li>敏感词内容审核</li><li>公众号扫码登陆</li></ul>',26)])])}const g=o(p,[["render",i]]);export{_ as __pageData,g as default};
